<script lang="ts">
 import {t,renderText,language,source} from './i18n';
  import {PWM_RAW_MAX, PWM_DEFAULT_DIMMER_MAX} from "./pwm";
 import {configurationState,configurationRevision,configurationCurrent} from './configuration-state';
 let snapshotRevision=$state(configurationRevision());
 import {readSavedConfiguration,saveConfiguration,inRange,type Firmware,type DeviceState} from './api';
 import {readChannels,savedChannels} from './channels';
 import {lightingKeys,decodeLighting,lightingPatch,timeLapseState,type LightingValues} from './advanced';
 import ActionButton from './ui/ActionButton.svelte';
 import DraftBar from './ui/DraftBar.svelte';
 import StateBadge from './ui/StateBadge.svelte';
 import ChannelIdentity from './ui/ChannelIdentity.svelte';
 import RawMeter from './ui/RawMeter.svelte';
 import LevelControl from './ui/LevelControl.svelte';
 let {active,busy,firmware,snapshot,stale,feedback,perform,command,refresh,readback,onedit}:{active:boolean;busy:boolean;firmware:Firmware;snapshot:DeviceState;stale:boolean;feedback:string;perform:(task:()=>Promise<void>,success:string,failure:string,pending:string)=>Promise<boolean>;command:(value:{pwms?:Record<string,number>;timewarp?:number})=>Promise<void>;refresh:()=>void;readback:()=>Promise<void>;onedit:()=>void}=$props();
 let draft=$state<LightingValues>(),base=$state<LightingValues>({}),attempted=$state(false),loading=$state(false),loadFailed=$state(false);
 const channels=$derived(Array.from({length:firmware.pwm_count},(_,i)=>i+1));
 function assessment(scope:'minimum'|'expert'){try{return {patch:draft?lightingPatch(draft,base,firmware.pwm_count,scope):{},error:''};}catch(e){return {patch:{},error:(e as Error).message};}}
 const minimum=$derived(assessment('minimum')),expert=$derived(assessment('expert')),mode=$derived(timeLapseState(snapshot,stale));
 const flags=[['higherminimum',source("lightingtools.raiseLowEndMinimum_60b13")],['oldfade',source("lightingtools.useOriginalDimmingAlgorithm_51c50")]];
 function set(key:string,value:unknown){if(draft){draft[key]=value;onedit();}}
 $effect(()=>{if(active&&!attempted&&!busy&&!$configurationState.recovery)void load();});
 async function load(refresh=false){attempted=true;loading=true;loadFailed=false;try{loadFailed=!await perform(async()=>{const next=decodeLighting(await readSavedConfiguration(lightingKeys(firmware.pwm_count),refresh),firmware.pwm_count);const identities=await readChannels(firmware.pwm_count,refresh);base=JSON.parse(JSON.stringify(next));draft=next;snapshotRevision=configurationRevision();savedChannels.set(identities);},source("lightingtools.lightingSettingsLoaded_d631a"),source("lightingtools.couldNotLoadLightingSettingsDraftKeptExplicitlyReload_6d257"),source("lightingtools.readingLightingSettings_48f70"));}finally{loading=false;}}
 async function save(scope:'minimum'|'expert',event:SubmitEvent){event.preventDefault();const result=assessment(scope);if(result.error||!Object.keys(result.patch).length||!configurationCurrent(snapshotRevision))return;await perform(async()=>{await saveConfiguration(result.patch,firmware);await readback();Object.assign(base,result.patch);},scope===source("lightingtools.minimum_bd164")?source("lightingtools.minimumSettingsSavedAndVerified_7d59e"):source("lightingtools.dimmingSettingsSavedAndVerified_b099d"),source("lightingtools.couldNotConfirmLightingSettingsDraftKeptReloadTo_ab8dd"),source("lightingtools.savingLightingSettings_fc109"));}
 async function preview(n:number){const value=draft?.[`pwm#${n}#min`];if(inRange(value,PWM_RAW_MAX))await command({pwms:{[n]:value}});}
</script>
<div hidden={!active} class="lighting-tools">
 <div class="heading"><div><h1>{$t("lightingtools.lightingTools_601b5")}</h1><p>{$t("lightingtools.temporaryOperationsAndAdvancedDimmingSettings_d9f0d")}</p></div></div>
 <section class="time-lapse" aria-label={$t("lightingtools.timeLapse_01f19")}><div class="operation"><div><h2>{$t("lightingtools.timeLapse_01f19")}</h2><p>{$t("lightingtools.reportedState_6e385")} <StateBadge tone={mode==='Active'?'active':mode==='Off'?'neutral':'draft'}>{$renderText(mode)}</StateBadge></p></div><div class="actions"><ActionButton disabled={busy||mode==='Unknown'||mode==='Uncertain'} onclick={()=>command({timewarp:1})}>{$t("lightingtools.startTimeLapse_86046")}</ActionButton><ActionButton secondary disabled={busy} onclick={()=>command({timewarp:0})}>{$t("lightingtools.stopTimeLapse_5e82a")}</ActionButton></div></div>
 <div class="read-state"><ActionButton secondary disabled={busy} onclick={refresh}>{$t("lightingtools.refreshLightingState_a6cf6")}</ActionButton></div><p>{$t("lightingtools.aTemporaryAcceleratedPlanningRunItChangesControllerOutput_277a4")}</p>
 <p>{$t("lightingtools.configurationReloadsAndRestartAlsoEndTimeLapseAfter_536f4")}</p></section>
 <nav aria-label={$t("lightingtools.lightingToolsSections_1b340")}><a href="#minimum-settings" onclick={e=>{e.preventDefault();document.getElementById('minimum-settings')?.scrollIntoView({block:'start'});}}>{$t("lightingtools.minimumOutput_9fc4c")}</a><a href="#expert-settings" onclick={e=>{e.preventDefault();document.getElementById('expert-settings')?.scrollIntoView({block:'start'});}}>{$t("lightingtools.expertDimming_1dd6d")}</a><a href="#schedules">{$t("lightingtools.schedulesAndRawCurves_eba01")}</a></nav>
 <div class="load-row">{#if draft||loadFailed}<ActionButton secondary disabled={busy} onclick={()=>load(true)}>{draft?$t("lightingtools.reloadLightingSettings_d4c6e"):$t("lightingtools.retryLightingSettings_3fc55")}</ActionButton>{/if}<p>{draft?$t("lightingtools.reloadReplacesBothSettingsDraftsNavigationKeepsUnsavedEdits_bbf37"):$t("lightingtools.savedSettingsLoadWhenThisPageOpensTimeLapse_a5410")}</p></div>
 {#if draft}
 <section id="minimum-settings" aria-label={$t("lightingtools.minimumOutputSettings_24196")}><h2>{$t("lightingtools.minimumOutput_9fc4c")}</h2><p>{$t("lightingtools.setAStoredMinimumFrom01000Raw0_f4d2f")}</p>
 <p class="notice">{$t("lightingtools.previewSendsALiveRawCommandFixedModeChannels_0d04d")}</p>
 <form onsubmit={e=>save('minimum',e)} novalidate><DraftBar {snapshotRevision} dirty={!!Object.keys(minimum.patch).length||!!minimum.error} {busy} feedback={$renderText(feedback)} disabled={!Object.keys(minimum.patch).length||!!minimum.error} label={$t("lightingtools.saveMinimumSettings_9296f")} scope={$language==='en'?$t("lightingtools.minimum_bd164")+' ':$t("lightingtools.minimum_bd164")} detail={$t("lightingtools.onlyChangedMinimumSettingsAreSavedOutputIsRead_05fba")}/>
 {#if minimum.error}<p class="error" role="alert">{$renderText(minimum.error)}</p>{/if}
 <div class="channel-grid">{#each channels as n}{@const key=`pwm#${n}#min`}<section class="channel-setting"><div class="row-title"><h3><ChannelIdentity number={n}/></h3><span>{$t("lightingtools.reported_73c20")}{stale?$t("app.readbackStale_e56ed"):''}: <strong>{snapshot.pwms[String(n)]} {$t("app.raw_ce158")}</strong></span></div><RawMeter value={snapshot.pwms[String(n)]} {stale}/>
 <p>{$t("lightingtools.savedMinimum_bcb8d")} {JSON.stringify(base[key])} {$t("app.raw_ce158")}{draft[`pwm#${n}#onoff`]===true?$t("lightingtools.binaryChannelMinimumDoesNotControlOnOffOutput_6ae11"):''}</p>
 {#if typeof base[key]!=='number'}<p>{$t("lightingtools.unknownStoredValueIsPreservedUntilExplicitlyReplaced_5a95d")}</p>{/if}
 <div class="minimum-control"><LevelControl id={`minimum-${n}`} label={$t("lightingtools.channelV0MinimumRaw_cb02f",{v0: n})} max={PWM_RAW_MAX} disabled={busy} bind:value={()=>typeof draft![key]==='number'?draft![key] as number:undefined,v=>set(key,v)}/><ActionButton secondary label={$t("lightingtools.previewChannelV0Minimum_e9edd",{v0: n})} disabled={busy||!inRange(draft[key],PWM_RAW_MAX)} onclick={()=>preview(n)}>{$t("lightingtools.preview_f1fbb")}</ActionButton></div></section>{/each}</div></form></section>
 <section id="expert-settings" aria-label={$t("lightingtools.expertDimmingSettings_07711")}><h2>{$t("lightingtools.expertDimming_1dd6d")}</h2><p>{$t("lightingtools.compatibilitySettingsForExistingLightingHardwareTheseAreRaw_84667")}</p>
 <form onsubmit={e=>save('expert',e)} novalidate><DraftBar {snapshotRevision} dirty={!!Object.keys(expert.patch).length||!!expert.error} {busy} feedback={$renderText(feedback)} disabled={!Object.keys(expert.patch).length||!!expert.error} label={$t("lightingtools.saveDimmingSettings_9648e")} scope={$language==='en'?$t("lightingtools.dimming_08611")+' ':$t("lightingtools.dimming_08611")} detail={$t("lightingtools.savesChangedCompatibilitySettingsWithoutSavingMinimumDrafts_a5b14")}/>
 {#if expert.error}<p class="error" role="alert">{$renderText(expert.error)}</p>{/if}
 <fieldset disabled={busy}><legend class="visually-hidden">{$t("lightingtools.dimmingSettings_e6883")}</legend><div class="flags">{#each flags as [key,label]}{#if typeof draft[key]==='boolean'}<label class="check"><input type="checkbox" checked={draft[key]===true} onchange={e=>set(key,e.currentTarget.checked)}/>{$renderText(label)}</label>{:else}<label>{$renderText(label)}<select value="unknown" onchange={e=>set(key,e.currentTarget.value==='true')}><option value="unknown" disabled>{$t("channelconfiguration.unknownPreserved_d5e08")}</option><option value="false">{$t("lightingdashboard.off_e3de5")}</option><option value="true">{$t("lightingtools.on_e0049")}</option></select></label>{/if}{/each}</div>
 <p>{$t("lightingtools.raiseLowEndMinimumAppliesTheFirmwareSCompatibility_886d0")}</p>
 <div class="channel-grid">{#each channels as n}{@const key=`pwm#${n}#max`}{@const smart=`pwm#${n}#nosmart`}<section class="channel-setting"><h3><ChannelIdentity number={n}/></h3><div class="expert-controls"><label>{$t("lightingtools.maximumRaw_b6369")}<input type="number" min="10" max={PWM_RAW_MAX} step="1" aria-label={$t("lightingtools.channelV0MaximumRaw_a2bb4",{v0: n})} value={typeof draft[key]==='number'?draft[key] as number:undefined} oninput={e=>set(key,e.currentTarget.value===''?undefined:Number(e.currentTarget.value))} aria-invalid={JSON.stringify(draft[key])!==JSON.stringify(base[key])&&(!inRange(draft[key],PWM_RAW_MAX)||(draft[key] as number)<10)}/></label>
 <p>{$t("lightingtools.savedMaximum_ab852")} {JSON.stringify(base[key])} {$t("app.raw_ce158")}</p>{#if typeof draft[smart]==='boolean'}<label class="check"><input type="checkbox" aria-label={$t("lightingtools.channelV0DisableSmartControlCompensation_06d1a",{v0: n})} checked={draft[smart]===true} onchange={e=>set(smart,e.currentTarget.checked)}/>{$t("lightingtools.disableSmartControlCompensation_d47f7")}</label>{:else}<label>{$t("lightingtools.smartcontrolDisable_e17ae")}<select aria-label={$t("lightingtools.channelV0DisableSmartControlCompensation_06d1a",{v0: n})} value="unknown" onchange={e=>set(smart,e.currentTarget.value==='true')}><option value="unknown" disabled>{$t("channelconfiguration.unknownPreserved_d5e08")}</option><option value="false">{$t("lightingdashboard.off_e3de5")}</option><option value="true">{$t("lightingtools.on_e0049")}</option></select></label>{/if}
 </div>{#if draft[`pwm#${n}#onoff`]===true||draft[smart]===true}<p>{$t("lightingtools.theFirmwareBypassesTheConfiguredMaximumForBinaryChannels_a6f09")}</p>{/if}</section>{/each}</div></fieldset></form></section>
 {:else}<p aria-live="polite">{loading?$t("lightingtools.readingLightingSettings_48f70"):loadFailed?$t("lightingtools.couldNotLoadLightingSettingsRetryTheReadNo_0c44e"):$configurationState.recovery?$t("channelconfiguration.configurationNotVerifiedCheckDeviceReadbackInRecoveryBefore_89f43"):$t("lightingtools.waitingToReadSavedLightingSettings_bc81e")}</p>{/if}
</div>
<style>
 .lighting-tools{font-size:15px;color:var(--sr-ink)}.heading,.operation,.load-row{display:flex;justify-content:space-between;align-items:center;gap:24px;margin:16px 0}.heading>div{min-width:0;max-width:100%;width:100%}.heading h1{overflow-wrap:anywhere;hyphens:auto;max-width:100%;font-size:var(--sr-title);font-weight:600;letter-spacing:-1px;margin:0}h2{font-size:20px;margin:0 0 12px}h3{font-size:15px;margin:0}p{font-size:13px;line-height:1.6;color:var(--sr-muted);max-width:110ch;margin:8px 0 14px}.time-lapse{border-left:2px solid var(--sr-accent);background:var(--sr-surface);padding:16px 20px}.operation{margin:0}.actions{display:flex;gap:12px;flex-wrap:wrap}nav{display:flex;gap:20px;flex-wrap:wrap;border:0;margin:16px 0}nav a{min-height:44px;display:inline-flex;align-items:center;font-size:14px}#minimum-settings,#expert-settings{margin:28px 0;scroll-margin-top:16px}.notice{border-left:2px solid var(--sr-accent);padding:8px 16px}.channel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 32px}.channel-setting{border-bottom:1px solid var(--sr-line);padding:16px 0;min-width:0}.row-title{display:flex;justify-content:space-between;align-items:center;gap:16px}.row-title span{font-size:13px;color:var(--sr-muted)}.row-title strong{color:var(--sr-ink);font-family:var(--sr-mono)}.minimum-control{display:grid;grid-template-columns:minmax(0,1fr) 90px;gap:12px;align-items:center}.read-state{margin:12px 0}.expert-controls{display:grid;grid-template-columns:180px minmax(0,1fr);column-gap:24px;align-items:center}.expert-controls>p{grid-row:2}.expert-controls>.check{grid-column:2;grid-row:1/3}.error{color:var(--sr-error)}fieldset{margin:0;border:0;padding:0;min-width:0}.flags{display:flex;gap:24px;flex-wrap:wrap}label{display:block;font-size:14px;margin:12px 0}.check{display:flex;align-items:center;gap:10px;min-height:44px}input[type=checkbox]{width:20px;height:20px;flex-shrink:0}input[type=number],select{display:block;width:100%;max-width:260px;min-height:44px;margin-top:8px;padding:8px 12px;color:var(--sr-ink);background:var(--sr-input);border:1px solid var(--sr-control-line);border-radius:var(--sr-radius);font-size:16px}input[aria-invalid=true]{border-color:var(--sr-error)}
 @media(max-width:800px){.channel-grid{grid-template-columns:1fr}.heading{align-items:flex-start;flex-direction:column}.operation{align-items:flex-start;flex-direction:column;gap:12px}.load-row{align-items:flex-start;flex-direction:column;gap:4px}.row-title{align-items:flex-start;flex-direction:column;gap:6px}.time-lapse{padding:16px}.flags{gap:0}.expert-controls{grid-template-columns:minmax(0,1fr)}.expert-controls>.check{grid-column:auto;grid-row:auto}.heading{gap:0;margin-top:8px}.heading p{margin-bottom:0}.minimum-control{grid-template-columns:minmax(0,1fr)}input[type=number],select{max-width:none}}
</style>
